    public function s1createTicket(Request $request) {
        try {
            $data = $request->json()->all();
            // echo "<pre>"; print_r($data); die;
            $rules = array(
                'api_token' => 'required|string',
                'dsId' => 'required|numeric',
                'sId' => 'required|numeric',
                'dId' => 'required|numeric',
                'tId' => 'required|numeric',
                'village' => 'string',
                'expected_farmers' => 'numeric',
                'expected_pda' => 'numeric',
                'product_1' => 'numeric',
                'crop_1' => 'numeric',
                'product_2' => 'numeric',
                'crop_2' => 'numeric',
                'product_3' => 'numeric',
                'crop_3' => 'numeric',
                'sp_name_1' => 'string',
                'sp_number_1' => 'numeric',
                'sp_name_2' => 'string',
                'sp_number_2' => 'numeric',
                'sp_name_3' => 'string',
                'sp_number_3' => 'numeric',
                'sp_name_4' => 'string',
                'sp_number_4' => 'numeric',
                'sp_name_5' => 'string',
                'sp_number_5' => 'numeric',
                'sp_name_6' => 'string',
                'sp_number_6' => 'numeric',
                'latitude' => 'string',
                'longitude' => 'string'
            );
            $validator = Validator::make($data, $rules);
            if ($validator->fails()) {
                return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
            } else {
                $api_token = $data['api_token'];
                $user = $this->findUser($api_token);
                if ($user && count($user) == '1') {
                    $user_id = $user[0]->id;
                    $user_type = $user[0]->user_type;
                    $data_source = DataSource::where('data_source_id', $data['dsId'])->first();
                    if (!$data_source) {
                        return $this->respondWithError("Invalid Data Source!");
