                                        sd.district,
                                        sdt.tehsil,
                                        t.village,
                                        dr.demo_code as demo_request_id,
                                        p1.product  AS product_1,
                                        p2.product  AS product_2,
                                        p3.product  AS product_3,
                                        c1.crop     AS crop_1,
                                        c2.crop     AS crop_2,
                                        c3.crop     AS crop_3,
                                        t.expected_farmers,
                                        t.expected_pda,
                                        t.sp_name_1,
                                        t.sp_number_1,
                                        t.sp_name_2,
                                        t.sp_number_2,
                                        t.sp_name_3,
                                        t.sp_number_3,
                                        t.sp_name_4,
                                        t.sp_number_4,
                                        t.sp_name_5,
                                        t.sp_number_5,
                                        t.sp_name_6,
                                        t.sp_number_6,
                                        t.language_id,
                                        t.user_farmer,
                                        lan.language,
                                        t.user_id,
                                        t.user_type,
                                        dd.name as dd_name,
                                        t.assign_to_dd as dd_id,
                                        IF( t.image_upload_type != '0', '" . $base_url1 . "/', '" . $base_url . "/' ) as base_url,
                                        t.uploaded_file, 
                                        t.uploadedByType,
                                        (CASE WHEN t.ticket_status='1' THEN 'ACTIVE' ELSE 'INACTIVE' END) as ticket_status
                                    FROM tickets t
                                    LEFT JOIN data_sources  d   ON t.data_source_id=d.data_source_id
                                    LEFT JOIN plan_atp  pat   ON pat.plan_atp_id=t.plan_atp_id
                                    LEFT JOIN languages  lan   ON lan.id=t.language_id

                                    LEFT JOIN states        s   ON t.state_id=s.state_id
                                    LEFT JOIN districts     sd  ON t.district_id=sd.district_id
                                    LEFT JOIN tehsils       sdt ON t.tehsil_id=sdt.tehsil_id
                                    LEFT JOIN products      p1  ON t.product_1_id=p1.product_id
                                    LEFT JOIN products      p2  ON t.product_2_id=p2.product_id
                                    LEFT JOIN products      p3  ON t.product_3_id=p3.product_id
                                    LEFT JOIN demo_request      dr  ON t.demo_request_id=dr.demo_request_id
                                    LEFT JOIN crops         c1  ON t.crop_1_id=c1.crop_id
                                    LEFT JOIN crops         c2  ON t.crop_2_id=c2.crop_id
                                    LEFT JOIN crops         c3  ON t.crop_3_id=c3.crop_id
                                    LEFT JOIN dhanuka_doctor  dd   ON dd.dd_id=t.assign_to_dd
                                    WHERE 
                                       (t.user_id in ('" . $user_id . "')  AND
                                        t.user_type='".$user_type."'  AND t.created_at <= '".date('Y-m-d')." 23:59:00' AND t.status != '0' AND t.ticket_status != '0' OR t.user_id in ('" . $bdo_ids . "')  AND
                                        t.user_type='bdo'  AND t.created_at <= '".date('Y-m-d')." 23:59:00' AND t.status != '0' AND t.ticket_status != '0' OR 
                                        t.ticket_id in  (SELECT ticket_id FROM tickets where user_id in ('".$dd_ids."') and user_type = 'dhanuka_doctor')) 
                                        AND t.created_at <= '".date('Y-m-d')." 23:59:00' AND t.status != '0' AND t.ticket_status != '0' 
                                    GROUP BY  
                                        t.ticket_id
                                    ORDER BY 
                                        FIELD(ticket_status, '1') DESC, t.ticket_id DESC
                                    LIMIT
                                        " . $offset . ", 50    
                                    "; //echo $query;die;
                    
                    }
                    
                    $ticket_history = DB::select(DB::raw($query)); 
                    $result = array_map(function ($value) {
                        return (array) $value;
                    }, $ticket_history);
                    
                    if ($ticket_history) {
                        return $this->respond([
                                    'status' => 'success',
                                    'status_code' => $this->getStatusCode(),
                                    'message' => 'Ticket History Found!',
                                    'data' => $result,
                        ]);
                    } else {
                        return $this->respondNotFound("No Record Found!");
                    }
                }
            }
        } catch (Exception $e) {
            return $this->respondInternalError("An error occurred while performing an action!");
        }
    }

    public function s1ticketdetail(Request $request) {
        $data = $request->json()->all();
        $rules = array(
            'api_token' => 'required|string',
            'tId' => 'required|numeric',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $data['api_token'];
            $user = $this->findUser($api_token);
            if ($user && count($user) == '1') {
                $user_id = $user[0]->id;
                $user_type = $user[0]->user_type;

                $ticket_id = $data['tId'];
                //$base_url = url('/');
                $base_url = "https://dhanuka-app.s3.ap-south-1.amazonaws.com";
                $query = "
                            SELECT 
                                d.data_source,
                                s.state,
                                sd.district,
                                sdt.tehsil,
                                t.village,
                                p1.product  AS product_1,
                                p2.product  AS product_2,
                                p3.product  AS product_3,
                                c1.crop     AS crop_1,
                                c2.crop     AS crop_2,
                                c3.crop     AS crop_3,
                                t.expected_farmers,
                                t.expected_pda,
                                t.sp_name_1,
                                t.sp_number_1,
                                t.sp_name_2,
                                t.sp_number_2,
                                t.sp_name_3,
                                t.sp_number_3,
                                t.sp_name_4,
                                t.sp_number_4,
                                t.sp_name_5,
                                t.sp_number_5,
                                t.sp_name_6,
                                t.sp_number_6,
                                t.demo_request_id,
                                t.user_farmer,

                                '" . $base_url . "/' as base_url,
                                t.uploaded_file, 
                                (CASE WHEN t.ticket_status='1' THEN 'ACTIVE' ELSE 'INACTIVE' END) as ticket_status
                            FROM tickets t
                            LEFT JOIN data_sources  d   ON t.data_source_id=d.data_source_id
                            LEFT JOIN states        s   ON t.state_id=s.state_id
                            LEFT JOIN districts     sd  ON t.district_id=sd.district_id
                            LEFT JOIN tehsils       sdt ON t.tehsil_id=sdt.tehsil_id

                            LEFT JOIN products      p1  ON t.product_1_id=p1.product_id
                            LEFT JOIN products      p2  ON t.product_2_id=p2.product_id
                            LEFT JOIN products      p3  ON t.product_3_id=p3.product_id

                            LEFT JOIN crops         c1  ON t.crop_1_id=c1.crop_id
                            LEFT JOIN crops         c2  ON t.crop_2_id=c2.crop_id
                            LEFT JOIN crops         c3  ON t.crop_3_id=c3.crop_id

                            WHERE 
                                t.ticket_id='" . $ticket_id . "'    AND
                                t.user_id='" . $user_id . "'        AND
                                t.user_type='" . $user_type . "'    
                            ";
                $ticket_detail = DB::select(DB::raw($query));
                $result = array_map(function ($value) {
                    return (array) $value;
                }, $ticket_detail);
                if ($result) {
                    return $this->respond([
                                'status' => 'success',
                                'status_code' => $this->getStatusCode(),
                                'message' => 'Ticket Details Successfully Found!',
                                'data' => $result,
                    ]);
                } else {
                    return $this->respondWithError("No Details Found!");
                }
            } else {
                return $this->respondWithConflict("Invalid Attempt!");
            }
        }
    }

    public function s1editticket(Request $request) {
        $data = $request->json()->all();
        $rules = array(
            'api_token' => 'required|string',
            'tId' => 'required|numeric',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $data['api_token'];
            $user = $this->findUser($api_token);
            if ($user && count($user) == '1') { 
                $user_id = $user[0]->id;
                $user_type = $user[0]->user_type;
                switch ($user_type) {
                    case "zonal" : $table = "zonal_manager_product_categories";
                        $key = "zonal_manager_id";
                        break;
                    case "regional" : $table = "regional_manager_product_categories";
                        $key = "regional_manager_id";
                        break;
                    case "area" : $table = "area_manager_product_categories";
                        $key = "area_manager_id";
                        break;
                    case "sales_regional" : $table = "sales_regional_manager_product_categories";
                        $key = "sales_regional_manager_id";
                        break;
                    case "sales_area" : $table = "sales_area_manager_product_categories";
                        $key = "sales_area_manager_id";
                        break;
                    case "bdo" : $table = "user_product_categories";
                        $key = "user_id";
                        break;
                    case "dhanuka_doctor" : $table = "dd_product_categories";
                        $key = "dd_id";
                        break;
                    case "marketing_supervisor" : $table = "sales_regional_manager_product_categories";
                        $key = "sales_regional_manager_id";
                        break;
