    public function s1selfParticipationSubmit(Request $request) {
        $data = $request->all();
        $rules = array(
            'apiToken' => 'required|string',
            'tId' => 'required|string',
            'desc' => 'required|string',
            'photo' => 'required|max:300000|mimes:jpg,png,jpeg'
