    public function createDemoRequest(Request $request) {
            $rules = array(
                'apiToken' => 'required|string',
                'cropId' => 'required',
                'productId' => 'required',
                'farmerName' => 'required',
                'stateId' => 'required',
                'districtId' => 'required',
                'tehsilId' => 'required',
                'pincode' => 'required',
                'villageId' => 'required',
                'contactNumber' => 'required',
                'showingDate' => 'required',
                'spray' => 'required',
                'farmer_type' => 'required'
            );
            $validator = Validator::make($request->all(), $rules);
            if ($validator->fails()) {
                return $this->respondValidationError('Main Fields Validation Failed.', $validator->errors());
            } else {
                $api_token = $request->input('apiToken');
                
                $user = $this->findUser($api_token);
                //echo "<pre>";print_r($request->input());die;
                if ($user && count($user) == '1') {

                    $product = DB::table('products')
                                ->where('product_id',$request->input('productId'))
                                ->get();
                    $crop    = DB::table('crops')
                                ->where('crop_id',$request->input('cropId'))
                                ->get();
                    $productname3 = substr($product[0]->product,0,3);
                    $cropname3 = substr($crop[0]->crop,0,3);

                    $fileName = "";
                    if($request->file('demoImage')){
                        $file=$request->file('demoImage');
                        // $fileName=time().rand(111,999).".".$file->getClientOriginalExtension();
                        // $file->move("assets/demoimage",$fileName);

                        //s3Upload
                        //$fileName = $file->getClientOriginalName();
                        $fileName = time().rand(111,999).".".$file->getClientOriginalExtension();
                        $sTempFileName = 'assets/demoimage/' . $fileName;
                        Storage::disk('s3')->put($sTempFileName, fopen($file, 'r+'),'public');
                        //
                    }

                    // $demo_code = $productname3.$cropname3.rand(100,999);
                    $demo_code  = $this->generateDemoNumber($productname3, $cropname3, $user[0]->ECN);
                    $demoRequest=new DemoRequest;
                    $user_id    = $user[0]->id;
                    $demoRequest= new DemoRequest;
                    $demoRequest->demo_code = $demo_code;
                    $demoRequest->dd_id=$user_id;
                    $demoRequest->crop_id=$request->input('cropId');
                    $demoRequest->product_id=$request->input('productId');
                    $demoRequest->acres=$request->input('acres');
                    $demoRequest->farmer_name=$request->input('farmerName');
                    $demoRequest->state_id=$request->input('stateId');
                    $demoRequest->district_id=$request->input('districtId');
                    $demoRequest->tehsil_id=$request->input('tehsilId');
                    $demoRequest->pincode=$request->input('pincode');
                    $demoRequest->village_id=$request->input('villageId');
                    $demoRequest->contact_number=$request->input('contactNumber');
                    $demoRequest->showing_date=$request->input('showingDate');
                    $demoRequest->spray=$request->input('spray');
                    $demoRequest->demoImage=($fileName)?$fileName:"";
                    $demoRequest->latitude=($request->input('latitude'))?$request->input('latitude'):"";
                    $demoRequest->longitude=($request->input('longitude'))?$request->input('longitude'):"";
                    $demoRequest->farmer_image=($request->input('farmer_image'))?$request->input('farmer_image'):"";
                    $demoRequest->farmer_type=($request->input('farmer_type'))?$request->input('farmer_type'):"";
                    $demoRequest->save();

                    return $this->respond([
                                'status' => 'success',
                                'status_code' => $this->getStatusCode(),
                                'message' => 'Demo request has been made Successfully.'
                                
                    ]);
                } else {
                    return $this->respondNotFound("Invalid Attempt !!");
                }
            }
        
    }

    public function DemoRequestList(Request $request) {
        $rules = array(
                'apiToken' => 'required|string',
                
            );
        $validator = Validator::make($request->all(), $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Main Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $request->input('apiToken');
            $user = $this->findUser($api_token);
            if ($user && count($user) == '1') {
                $dd_id = $user[0]->id;
                $user_type = $user[0]->user_type;
                //$base_url = url('/');
                $base_url = "https://dhanuka-app.s3.ap-south-1.amazonaws.com";
                if ($user_type == 'zonal') 
                {
                    //regional manager
                    $ddData = DB::table('dhanuka_doctor')
                              ->where('zonal_manager_id',$dd_id)
                              ->where('status','1')
                              ->select('dd_id')
                              ->get();
                    $ddresult = array(); 
                    if (isset($ddData) && !empty($ddData)) 
                    {
                        $ddDatass = json_decode(json_encode($ddData),true);
                        
                        foreach ($ddDatass as $key => $value) { 
                            if (is_array($value)) 
                            { 
                                $ddresult = array_merge($ddresult, array_flatten($value)); 
                            } 
                            else 
                            { 
                              $ddresult[$key] = $value; 
                            } 
                        } 
                    }
                    // echo "<pre>"; print_r($ddresult); die;
                    if ($request->input('status') == 'Evaluated') {
                        $demoRequest =DemoRequest::join('villages','villages.village_id','=','demo_request.village_id','left')
