                        }
                        
                        if ($request->has('status')) {
                            $demoPoor->where('demo_request.status','Poor');
                        }
                        $demoPoor = $demoPoor->count();

                        //Overdue demo count
                        $demoOverdue =DemoRequest::where('demo_request.status','Overdue');
