    public function TestimonialList(Request $request) {
        $rules = array(
                'apiToken' => 'required|string'
            );
        //$base_url = url('/');
        $base_url = "https://dhanuka-app.s3.ap-south-1.amazonaws.com";
        $validator = Validator::make($request->all(), $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Main Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $request->input('apiToken');
            $user = $this->findUser($api_token);
            if ($user && count($user) == '1') {
                $user_id = $user[0]->id;
                $user_type = $user[0]->user_type;
                if($user_type == 'bdo')
                {
                    $testimonial_type = $request->input('testimonial_type');
                    // $rating = $request->input('rating');
                    $from = $request->input('from');
                    $to = $request->input('to');
                    $crop = $request->input('crop');
                    $product = $request->input('product');
                    $dd_id = $request->input('dd_id');
                    $getddArray = array(); 
                    $getDD = DhanukaDoctor::where('bdo_id',$user_id)->where('status','1')->select('dd_id')->get()->toArray();
                    if(count($getDD) > 0)
                    {
                        foreach ($getDD as $keyDD => $valueDD) {
                            array_push($getddArray, $valueDD['dd_id']);
                            }
                    } 
                    $testimonialList1 = DB::table('testimonials as t')
                                    ->join('crops','crops.crop_id','=','t.crop_id','left')
                                    ->join('products','products.product_id','=','t.product_ids','left');
                    if($request->input('dd_id') != '' && $request->input('myself') != '')
                    {
                        $newddArray = explode(',', $request->input('dd_id'));
                       
