                        $query->whereIn('t.user_id',$newddArray)->where('t.user_type','dhanuka_doctor')->where('t.status','1')
                        ->orWhere(['t.user_id' => $user_id, 't.user_type' => $user_type, 't.status' => '1']);
                        });
                        
