                                    $testimonialList->orWhereIn('testimonials.self_participation_id',function($query) use ($ddresult)
                                    {
                                        $query->select('self_participation_id')->from('testimonials')->whereIn('user_id',$ddresult)->where('user_type','dhanuka_doctor');
                                    });
                                }
                                else
                                {
                                    $testimonialList->whereIn('testimonials.self_participation_id',function($query) use ($ddresult)
                                    {
                                        $query->select('self_participation_id')->from('testimonials')->whereIn('user_id',$ddresult)->where('user_type','dhanuka_doctor');
                                    });
                                }
                            }
                            if (count($bdoresult) > 0) {
                                if (count($rsmresult) > 0 || count($asmresult) > 0 || count($ddresult) > 0 ) {
                                    $testimonialList->orWhereIn('testimonials.self_participation_id',function($query) use ($bdoresult)
                                    {
