                            $testimonialList->Where('testimonials.user_type','sales_regional');
                        }

                        if ($request->has('asm')) {
                            $asm=$request->input('asm');
                            if ($request->has('rsm')) {
                                $testimonialList->orWhere('testimonials.user_id',$asm);
                                $testimonialList->Where('testimonials.user_type','sales_area');
                            }
                            else
                            {
                                $testimonialList->Where('testimonials.user_id',$asm);
                                $testimonialList->Where('testimonials.user_type','sales_area');
                            }
                        }

                        if ($request->has('bdo_id')) {
                            $bdo_id=$request->input('bdo_id');
                            if ($request->has('asm')) {
                                $testimonialList->orWhere('testimonials.user_id',$bdo_id);
                                $testimonialList->Where('testimonials.user_type','bdo');
                            }
                            else
                            {
                                $testimonialList->Where('testimonials.user_id',$bdo_id);
                                $testimonialList->Where('testimonials.user_type','bdo');
