                        }

                        if ($request->has('dd_id')) {
                            $dd_id=$request->input('dd_id');
                            if ($request->has('bdo_id')) {
                                $testimonialList->orWhere('testimonials.user_id',$dd_id);
                                $testimonialList->Where('testimonials.user_type','dhanuka_doctor');
                            }
                            else
                            {
                                $testimonialList->Where('testimonials.user_id',$dd_id);
                                $testimonialList->Where('testimonials.user_type','dhanuka_doctor');
                            }
                            
                        }

                        if ($request->has('testimonial_type')) {
                            $testimonial_type = $request->input('testimonial_type');
