                        }
                        
                        
                        
                        $testimonialList = $testimonialList->where('testimonials.status',1)->orderBy('testimonials.created_at', 'DESC')
                        ->select('testimonials.*','crops.crop','products.product')
                        ->get();
                }

               // print_r($testimonialList);die;
                if (isset($testimonialList) && !empty($testimonialList)) {
                    foreach ($testimonialList as $key => $value) {
                        $testimonialList[$key]->uploaded_file = $base_url.'/'.$testimonialList[$key]->uploaded_file;
                        $testimonialList[$key]->crop = ($testimonialList[$key]->crop)?$testimonialList[$key]->crop:"";
                        $testimonialList[$key]->product = ($testimonialList[$key]->product)?$testimonialList[$key]->product:"";
                        $testimonialList[$key]->unique_testimonial_id = ($testimonialList[$key]->unique_testimonial_id)?$testimonialList[$key]->unique_testimonial_id:""; 
                        $testimonialList[$key]->uploaded_at = ($testimonialList[$key]->uploaded_at)?$testimonialList[$key]->uploaded_at:"";  
                    }

                    if ($user_type == 'marketing_supervisor' || $user_type == 'zonal' || $user_type == 'regional' || $user_type == 'area' || $user_type == 'sales_regional' || $user_type == 'sales_area' || $user_type == 'dhanuka_doctor') {
                        foreach ($testimonialList as $key => $value) {
                            $query = "SELECT
                                        CONCAT_WS(  
                                                    '\n',
                                                    NULLIF(zm.zonal_manager_name, ''),
                                                    NULLIF(rm.regional_manager_name, ''),
                                                    NULLIF(am.area_manager_name, ''),
                                                    NULLIF(srm.sales_regional_manager_name, ''),
                                                    NULLIF(sam.sales_area_manager_name, ''),
                                                    NULLIF(u.name, ''),
                                                    NULLIF(dd.name, ''),
                                                    NULLIF(ms.marketing_supervisor_name, '')
                                                ) AS supervisor_name,
                                        tr.testimonial_id,
                                        tr.supervisor_id,
                                        tr.supervisor_type,
                                        tr.rating,    
                                        tr.created_at
                                    FROM   testimonial_rating  tr
                                    LEFT JOIN users u ON tr.supervisor_id=u.id AND tr.supervisor_type = 'bdo'
                                    LEFT JOIN zonal_managers zm ON tr.supervisor_id=zm.zonal_manager_id AND tr.supervisor_type ='zonal'
                                    LEFT JOIN regional_managers rm ON tr.supervisor_id=rm.regional_manager_id AND tr.supervisor_type='regional'
                                    LEFT JOIN area_managers am ON tr.supervisor_id=am.area_manager_id AND tr.supervisor_type='area'
                                    LEFT JOIN sales_regional_managers srm ON tr.supervisor_id=srm.sales_regional_manager_id AND tr.supervisor_type='sales_regional'
                                    LEFT JOIN   sales_area_managers     sam ON tr.supervisor_id=sam.sales_area_manager_id AND tr.supervisor_type='sales_area'
                                    LEFT JOIN   dhanuka_doctor dd ON tr.supervisor_id=dd.dd_id AND tr.supervisor_type='dhanuka_doctor'
                                    LEFT JOIN   marketing_supervisor ms ON tr.supervisor_id=ms.marketing_supervisor_id AND tr.supervisor_type='marketing_supervisor'
                                    WHERE  tr.testimonial_id='".$testimonialList[$key]->self_participation_id."' 
                                    ORDER BY tr.testimonial_id DESC";
                            $testimonial_rating = collect(DB::select($query)); 
                            
                            if (count($testimonial_rating) > 0) {
                                $testimonialList[$key]->testimonial_rating = $testimonial_rating;
                            } 
                            else
                            {
                                $testimonialList[$key]->testimonial_rating = [];
                            }      
                        }
                    }

                    foreach ($testimonialList as $key => $value) {
                        $query = "SELECT
                                    CONCAT_WS(  
                                                '\n',
                                                NULLIF(zm.zonal_manager_name, ''),
                                                NULLIF(rm.regional_manager_name, ''),
                                                NULLIF(am.area_manager_name, ''),
                                                NULLIF(srm.sales_regional_manager_name, ''),
                                                NULLIF(sam.sales_area_manager_name, ''),
                                                NULLIF(u.name, ''),
                                                NULLIF(dd.name, ''),
                                                NULLIF(ms.marketing_supervisor_name, '')
                                            ) AS supervisor_name,
                                    tr.testimonial_id,
                                    tr.supervisor_id,
                                    tr.supervisor_type,
                                    tr.rating,    
                                    tr.created_at
                                FROM   testimonial_rating  tr
                                LEFT JOIN users u ON tr.supervisor_id=u.id AND tr.supervisor_type = 'bdo'
                                LEFT JOIN zonal_managers zm ON tr.supervisor_id=zm.zonal_manager_id AND tr.supervisor_type ='zonal'
                                LEFT JOIN regional_managers rm ON tr.supervisor_id=rm.regional_manager_id AND tr.supervisor_type='regional'
                                LEFT JOIN area_managers am ON tr.supervisor_id=am.area_manager_id AND tr.supervisor_type='area'
                                LEFT JOIN sales_regional_managers srm ON tr.supervisor_id=srm.sales_regional_manager_id AND tr.supervisor_type='sales_regional'
                                LEFT JOIN   sales_area_managers     sam ON tr.supervisor_id=sam.sales_area_manager_id AND tr.supervisor_type='sales_area'
                                LEFT JOIN   dhanuka_doctor dd ON tr.supervisor_id=dd.dd_id AND tr.supervisor_type='dhanuka_doctor'
                                LEFT JOIN   marketing_supervisor ms ON tr.supervisor_id=ms.marketing_supervisor_id AND tr.supervisor_type='marketing_supervisor'
                                WHERE  tr.testimonial_id='".$testimonialList[$key]->self_participation_id."' 
                                ORDER BY tr.testimonial_id DESC";
                        $testimonial_rating = collect(DB::select($query)); 
                        
                        if (count($testimonial_rating) > 0) {
                            $testimonialList[$key]->testimonial_rating = $testimonial_rating;
                        } 
                        else
                        {
                            $testimonialList[$key]->testimonial_rating = [];
                        }     


                        $checkrated = DB::table('testimonial_rating') 
                                      ->where('testimonial_id',$testimonialList[$key]->self_participation_id)
                                      ->select('rating')
                                      ->orderBy('id','desc')
                                      ->get();
                                      //->select(DB::raw('avg(rating) as rating'))
                        if (count($checkrated) > 0) {
                            $testimonialList[$key]->rated = $checkrated[0]->rating; 
                        }
                        else
                        {
                            $testimonialList[$key]->rated = "0";
                        }
                    }
                    $testimonialData = [];
                    if ($request->has('rating')) {
                        $rating = explode(',', $request->input('rating'));
                        foreach ($rating as $key => $value) {
                            foreach ($testimonialList as $Tkey => $Tvalue) {
                                if ($testimonialList[$Tkey]->rated == $rating[$key]) {
                                    $testimonialData[] = $testimonialList[$Tkey];
                                }
                            }
                        }
                    }
                    else
                    {
                        $testimonialData = $testimonialList; 
                    }
                    return $this->respond([
