                                                            NULLIF(u.name, ''),
                                                            NULLIF(dd.name, ''),
                                                            NULLIF(ms.marketing_supervisor_name, '')
                                                        ) AS supervisor_name,
                                                tr.testimonial_id,
                                                tr.supervisor_id,
                                                tr.supervisor_type,
                                                tr.rating,    
                                                tr.created_at
                                            FROM   testimonial_rating  tr
                                            LEFT JOIN users u ON tr.supervisor_id=u.id AND tr.supervisor_type = 'bdo'
                                            LEFT JOIN zonal_managers zm ON tr.supervisor_id=zm.zonal_manager_id AND tr.supervisor_type ='zonal'
                                            LEFT JOIN regional_managers rm ON tr.supervisor_id=rm.regional_manager_id AND tr.supervisor_type='regional'
                                            LEFT JOIN area_managers am ON tr.supervisor_id=am.area_manager_id AND tr.supervisor_type='area'
                                            LEFT JOIN sales_regional_managers srm ON tr.supervisor_id=srm.sales_regional_manager_id AND tr.supervisor_type='sales_regional'
                                            LEFT JOIN   sales_area_managers     sam ON tr.supervisor_id=sam.sales_area_manager_id AND tr.supervisor_type='sales_area'
                                            LEFT JOIN   dhanuka_doctor dd ON tr.supervisor_id=dd.dd_id AND tr.supervisor_type='dhanuka_doctor'
                                            LEFT JOIN   marketing_supervisor ms ON tr.supervisor_id=ms.marketing_supervisor_id AND tr.supervisor_type='marketing_supervisor'
                                            WHERE  tr.testimonial_id='".$s_fl_data[$key]->self_participation_id."' 
                                            ORDER BY tr.testimonial_id DESC";
                                    $bdos_testimonial_rating = collect(DB::select($query)); 
                                    
                                    if (count($bdos_testimonial_rating) > 0) {
                                        $s_fl_data[$key]->bdo_testimonial_rating = $bdos_testimonial_rating;
                                    } 
                                    else
                                    {
                                        $s_fl_data[$key]->bdos_testimonial_rating = [];
                                    }     


                                    $checkrated = DB::table('testimonial_rating') 
                                                  ->where('testimonial_id',$s_fl_data[$key]->self_participation_id)
                                                  ->select('rating')
                                                  ->orderBy('id','desc')
                                                  ->get();
                                                  //->select(DB::raw('avg(rating) as rating'))
                                    if (count($checkrated) > 0) {
                                        $s_fl_data[$key]->rated = $checkrated[0]->rating; 
                                    }
                                    else
                                    {
                                        $s_fl_data[$key]->rated = "0";
                                    }
                                }

                                $bdosTestimonialData = [];
                                if ($request->has('rating')) {
                                    $rating = explode(',', $request->input('rating'));
                                    foreach ($rating as $key => $value) {
                                        foreach ($s_fl_data as $Tkey => $Tvalue) {
                                            if ($s_fl_data[$Tkey]->rated == $rating[$key]) {
                                                $bdosTestimonialData[] = $s_fl_data[$Tkey];
                                            }
                                        }
                                    }
                                }
                                else
                                {
                                    $bdosTestimonialData = $s_fl_data; 
                                }

                            $totalS_flTestimonials = count($bdosTestimonialData);

                            // $s_flCount = 0;
                            // foreach ($testimonialList as $key => $value) {
                            //     foreach ($s_flresult as $s_flresultkey => $s_flresultvalue) {
                            //         if ($testimonialList[$key]->user_id == $s_flresult[$s_flresultkey] && $testimonialList[$key]->user_type == 'bdo') 
                            //         {
                            //             $s_flCount = $s_flCount + 1;
                            //         }
                            //     }
                            // }
                            // $s_flresultcount = count($s_flresult);
                            // if ($s_flCount != 0) {
                            //     $totalS_flTestimonials = $s_flCount / $s_flresultcount;
                            // }
                            // else
                            // {
                            //     $totalS_flTestimonials = 0;
                            // }
                             
                        }
                        else
                        {
                            $totalS_flTestimonials = 0;
                        }
                    }
                    else{
                        $totalBd_flTestimonials = 0;
                        $totalS_flTestimonials = 0;
                    }

                    //checking testimonial rating not less then 5
                    // foreach ($testimonialList as $key => $value) {
                    //     if ($testimonialList[$key]->rated < 5) {
                    //        unset($testimonialList[$key]);
                    //     }
                    // }
                    $testimonialData = [];
                    if ($request->has('rating')) {
                        $rating = explode(',', $request->input('rating'));
                        foreach ($rating as $key => $value) {
                            foreach ($testimonialList as $Tkey => $Tvalue) {
                                if ($testimonialList[$Tkey]->rated == $rating[$key]) {
                                    $testimonialData[] = $testimonialList[$Tkey];
                                }
                            }
                        }
                    }
                    else
                    {
                        $testimonialData = $testimonialList; 
                    }

                    $totalTestimonials = count($testimonialData);
                    //$totalTestimonials = $totalBd_flTestimonials + $totalS_flTestimonials;
                    $result = array('totalTestimonials' => $totalTestimonials, 'totalBd_flTestimonials' => $totalBd_flTestimonials, 'totalS_flTestimonials' => $totalS_flTestimonials, 'testimonialData' => $testimonialData);
                    return $this->respond([
                                            'status' => 'success',
                                            'status_code' => $this->getStatusCode(),
                                            'message' => 'Testimonial list.',
                                            'data' => $result
                                ]);
                }
                else
                {   
                    $result = array('totalTestimonials' =>0, 'totalBd_flTestimonials' => 0, 'totalS_flTestimonials' => 0, 'testimonialData' => []);
                    return $this->respond([
                                            'status' => 'success',
                                            'status_code' => $this->getStatusCode(),
                                            'message' => 'No data found.',
                                            'data' => $result
                                ]);
                }
                
            } else {
                return $this->respondNotFound("Invalid Attempt !!");
            }
        }
    }

    public function testimonialRating(Request $request)
    {
        $rules = array(
            'apiToken' => 'required|string',
            'testimonial_id' => 'required',
            'rating' => 'required'
        );
        //$base_url = url('/');
        $base_url = "https://dhanuka-app.s3.ap-south-1.amazonaws.com";
        $validator = Validator::make($request->all(), $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Main Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $request->input('apiToken');
            $user = $this->findUser($api_token);
            if ($user && count($user) == '1') {
                $user_id = $user[0]->id;
                $user_type = $user[0]->user_type;
                $testimonial_id = $request->input('testimonial_id');
                $rating = $request->input('rating');
                $checkTating = DB::table('testimonial_rating')
                               ->where('supervisor_id',$user_id)
                               ->where('supervisor_type',$user_type)
                               ->where('testimonial_id',$testimonial_id)
                               ->get();
                if (count($checkTating)>0) 
                {
                    return $this->respond([
                                    'status' => 'success',
                                    'status_code' => $this->getStatusCode(),
                                    'message' => 'You have already rated this testimonial.'
                        ]);
                }
                else
                {
                    $ratData = array(
                                        'testimonial_id' => $testimonial_id,
                                        'rating' => $rating,
                                        'supervisor_id' => $user_id,
                                        'supervisor_type' => $user_type,
                                        'created_at' => date('Y-m-d H:i:s')
                                    );
                    $rate = DB::table('testimonial_rating')->insert($ratData);
                    if ($rate) {
                        return $this->respond([
                                    'status' => 'success',
                                    'status_code' => $this->getStatusCode(),
                                    'message' => 'Testimonial rated successfully.'
                        ]);
                    }
                    else
                    {
                        return $this->respond([
                                    'status' => 'error',
                                    'status_code' => $this->getStatusCode(),
                                    'message' => 'Please try again.'
                        ]);
                    }
                }
            } else {
                return $this->respondNotFound("Invalid Attempt !!");
            }
        }
    }

    public function s1updateticketimagetest(Request $request) {
        $data = $request->all();
        $rules = array(
            'api_token' => 'required|string',
            'tId' => 'required|string',
            'photo' => 'required|max:300000|mimes:jpg,png,jpeg',
            'updated_at' => 'required'
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Main Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $data['api_token'];
            $ticket_id = $data['tId'];
            $file = $request->file('photo');
            $latitude = (isset($data['latitude']) ? $data['latitude'] : '');
            $longitude = (isset($data['longitude']) ? $data['longitude'] : '');
            $updated_at = (isset($data['updated_at'])?$data['updated_at']:'');

            if ($request->hasFile('photo')) {
                if ($request->file('photo')->isValid()) {
                    $user = $this->findUser($api_token);
                    if ($user && count($user) == '1') {
                        $user_id = $user[0]->id;
                        $user_type = $user[0]->user_type;
                        $ticket_check = Ticket::where('ticket_id', $ticket_id)->first();
                        if ($ticket_check) {

                            $extension = pathinfo($file->getClientOriginalName(), PATHINFO_EXTENSION);
                            // $fileName = "F_" . $ticket_check->ticket_no . "_" . md5(time() . rand()) . str_replace($file->getClientOriginalName(), '', $file->getClientOriginalName()) . '.' . $extension;
                            // $destinationPath = 'assets/tickets/';
                            // $sTempFileName = 'assets/tickets/' . $fileName;
                            // $request->file('photo')->move($destinationPath, $fileName);
                            //s3Upload
                            //$fileName = $file->getClientOriginalName();
                            $fileName = "F_" . $ticket_check->ticket_no . "_" . md5(time() . rand()) . str_replace($file->getClientOriginalName(), '', $file->getClientOriginalName()) . '.' . $extension;
                            $sTempFileName = 'assets/tickets/' . $fileName;
                            Storage::disk('s3')->put($sTempFileName, fopen($file, 'r+'),'public');
                            //
                            $userType1 = "";
                            if ($user_type == 'bdo') 
                            {
                                $getUserDesignation = DB::table('users')
                                                      ->where('id',$user_id)
                                                      ->where('status','1')
                                                      ->select('designation')
                                                      ->get();
                                $userType1 = $getUserDesignation[0]->designation;

                            }
                            elseif ($user_type == 'dhanuka_doctor') 
                            {
                                $getDdDesignation = DB::table('dhanuka_doctor')
                                                      ->where('dd_id',$user_id)
                                                      ->where('status','1')
                                                      ->select('designation')
                                                      ->get();
                                $userType1 = $getDdDesignation[0]->designation;
                            }
                            elseif ($user_type == 'sales_regional') 
                            {
                                $userType1 = 'RSM';
                            }
                            elseif ($user_type == 'sales_area') 
                            {
                                $userType1 = 'ASM';
                            }
                            elseif ($user_type == 'marketing_supervisor') 
                            {
                                $userType1 = 'Marketing Supervisor';
                            }
                            else
                            {
                                $userType1 = $user_type;
                            }

                            $checkTicketUpload = DB::table('tickets')
                                                 ->where('ticket_id','=',$ticket_id)
                                                 ->where('uploadedByType','=','')
                                                 ->get();
                            if (count($checkTicketUpload) > 0) {
                                $updateImage = Ticket::where('ticket_id', $ticket_id)->update(['uploaded_file' => $sTempFileName, 'image_upload_type' => '1', 'latitude' => $latitude, 'longitude' => $longitude, 'uploadedBy' => $user_id, 'uploadedByType' => $userType1, 'updated_at' => $updated_at]);

                                if ($updateImage) {
                                    //$base_url = url('/');
                                    $base_url = "https://dhanuka-app.s3.ap-south-1.amazonaws.com";
                                    $imageUrl = $base_url . '/' . $sTempFileName;
                                    $data = array('url' => $imageUrl);
                                    return $this->respond([
                                                'status' => 'success',
                                                'status_code' => $this->getStatusCode(),
                                                'message' => 'File Successfully Uploaded!',
                                                'data' => $data
                                    ]);
                                } else {
                                    return $this->respondInternalError("Failed to upload file!");
                                }
                            }
                            else
                            {
                                return $this->respond([
                                                'status' => 'success',
                                                'status_code' => $this->getStatusCode(),
                                                'message' => 'File Already Uploaded!',
                                                'data' => ""
                                    ]);
                            }

                            
                        } else {
                            return $this->respondNotFound("Invalid Ticket !!");
                        }
                    } else {
                        return $this->respondWithError("Invalid Attempt !!");
                    }
                } else {
                    return $this->respondWithError("Invalid File !!");
                }
            } else {
                return $this->respondWithError("File Not Found !!");
            }
        }
    }

