                                    $query .=" afb.ticket_id in  (SELECT ticket_id FROM tickets where assign_to_dd = '".$request->input('dd_id')."')";
                                }
                                elseif (!$request->has('rsm') && $request->has('asm') && $request->has('bdo_id') && !$request->has('dd_id')) {
                                    $query .=" afb.ticket_id in  (SELECT ticket_id FROM tickets where user_id = '".$request->input('bdo_id')."' and user_type = 'bdo')";
                                }
                                elseif (!$request->has('rsm') && !$request->has('asm') && $request->has('bdo_id') && !$request->has('dd_id')) {
                                    $query .=" afb.ticket_id in  (SELECT ticket_id FROM tickets where user_id = '".$request->input('bdo_id')."' and user_type = 'bdo')";
                                }
                                elseif (!$request->has('rsm') && !$request->has('asm') && $request->has('bdo_id') && $request->has('dd_id')) {
                                    $query .=" afb.ticket_id in  (SELECT ticket_id FROM tickets where assign_to_dd = '".$request->input('dd_id')."')";
                                }
                                elseif (!$request->has('rsm') && $request->has('asm') && !$request->has('bdo_id') && $request->has('dd_id')) {
                                    $query .=" afb.ticket_id in  (SELECT ticket_id FROM tickets where assign_to_dd = '".$request->input('dd_id')."')";
                                }
                                elseif ($request->has('rsm') && $request->has('asm') && $request->has('bdo_id') && $request->has('dd_id')) {  
                                    $query .=" afb.ticket_id in  (SELECT ticket_id FROM tickets where assign_to_dd = '".$request->input('dd_id')."')";
                                }
                                elseif (!$request->has('rsm') && !$request->has('asm') && !$request->has('bdo_id') && $request->has('dd_id')) {  
                                    $query .=" afb.ticket_id in  (SELECT ticket_id FROM tickets where assign_to_dd = '".$request->input('dd_id')."')";
                                } 
                            }
                            else
                            {   
                                //$query .=" afb.ticket_id in ('".$finalData."') ";
                                $query .=" afb.user_id = '".$user_id."' AND afb.user_type = '".$user_type."' ";

                                // if($request->has('from_date') && $request->has('to_date')){
                                //     $from_date=$request->input('from_date');
                                //     $to_date=$request->input('to_date');
                                    
                                //     if (!empty($users) && isset($users)) {
                                //         $query .=" OR t.ticket_id in  (SELECT ticket_id FROM tickets where user_id in ('".$users."') and user_type = 'bdo') and `t`.`created_at` BETWEEN '".$from_date." 00:00:00 ' and '".$to_date." 23:59:59 '";
                                //     }
                                    
                                //     if (!empty($dd_ids) && isset($dd_ids)) { 
                                //         $query .=" OR t.ticket_id in  (SELECT ticket_id FROM tickets where assign_to_dd in ('".$dd_ids."')) and `t`.`created_at` BETWEEN '".$from_date." 00:00:00 ' and '".$to_date." 23:59:59 '";
                                //     }
                                // }
                                // else
                                // {
                                //     if (!empty($users) && isset($users)) {
                                //         $query .=" OR t.ticket_id in  (SELECT ticket_id FROM tickets where user_id in ('".$users."') and user_type = 'bdo')";
                                //     }
                                    
                                //     if (!empty($dd_ids) && isset($dd_ids)) { 
                                //         $query .=" OR t.ticket_id in  (SELECT ticket_id FROM tickets where assign_to_dd in ('".$dd_ids."'))";
                                //     }
                                // }
                                
                            }

                            if($request->has('from_date') && $request->has('to_date')){ 
                                $from_date=$request->input('from_date');
                                $to_date=$request->input('to_date');
                                $query .=" AND `afb`.`creation_at` BETWEEN '".$from_date." 00:00:00 ' and '".$to_date." 23:59:59 '";
                            }
                            // else
                            // {   
                            //     $query .=" t.created_at <= '".date('Y-m-d')." 23:59:00'";
                            // }
                            

                            if ($request->has('product')) {
                                $product=$request->input('product');
                                $query .=" AND (`t`.`product_1_id` = '".$product."' OR `t`.`product_2_id` = '".$product."' OR `t`.`product_3_id` = '".$product."')";
                            }

                            if ($request->has('crop')) {
                                $crop=$request->input('crop');
                                $query .=" AND (`t`.`crop_1_id` = '".$crop."' OR `t`.`crop_2_id` = '".$crop."' OR `t`.`crop_3_id` = '".$crop."')";
                            }
                            
                            $query .=" GROUP BY  
                                t.ticket_id
                            ORDER BY
                                FIELD(ticket_status, '1') DESC, t.ticket_id DESC
                            ";
                    $ticket_history = DB::select(DB::raw($query));
                    $result = array_map(function ($value) {
                        return (array) $value;
                    }, $ticket_history);
                    if ($ticket_history) {
                        foreach ($result as $key => $value) {
                            if (empty($result[$key]['longitude']) || is_null($result[$key]['longitude']) ) {
                                $result[$key]['longitude'] = 0;
                            }

                            if (empty($result[$key]['latitude']) || is_null($result[$key]['latitude']) ) {
                                $result[$key]['latitude'] = 0;
                            }

                            if (!empty($result[$key]['feedbackImage'])) {
                                $result[$key]['feedbackImage'] = $base_url . '/assets/atpfeedbackimage/' . $result[$key]['feedbackImage'];
                            }

                              $heightLightCount = DB::table('ticket_highlights')
                              ->where('ticket_id',$value['tID'])
                              ->select('*')
                              ->count();
                              $result[$key]['heightLightCount'] = $heightLightCount;
                        }
                        return $this->respond([
                                    'status' => 'success',
                                    'status_code' => $this->getStatusCode(),
                                    'message' => 'Ticket History Found!',
                                    'data' => $result,
                        ]);
                    } else {
                        //return $this->respondNotFound("No Record Found!");
                        return $this->respond([
                                    'status' => 'success',
                                    'status_code' => $this->getStatusCode(),
                                    'message' => 'No Record Found!',
                                    'data' => [],
                        ]);
                    }
                
            }else {
                return $this->respondNotFound("Invalid Attempt !!");
            }
        }
    
    }
   

