        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $data['apiToken'];
            // $user = $this->findUser($api_token);
            $user = User::where('api_token', $api_token)->get()->toArray();

            if ($user && count($user) == 1) {
                $user_id = $user[0]['id'];
                $user_type = 'bdo';

                $app_version = isset($data['app_version']) ? $data['app_version'] : '';
                $app_version_data = array(
                    'user_id' => $user_id,
                    'user_type' => $user_type,
                    'app_version' => $app_version
                );
                $insert_version = AppVersion::firstOrCreate($app_version_data);

                try {
                    $districts = $user[0]['districts'];
                    if($districts!=NULL) {
                        $districts = str_replace('"', "", str_replace('[', "",str_replace(']', "",$user[0]['districts'])));
                        $districtArr = explode(',',$districts);
                        if(count($districtArr)>0) {
                            $district_list = District::whereIn('district_id', $districtArr)->get()->toArray();
