    /* Add Market */
    public function adddistmarket(Request $request) {
        $data = $request->all();
        $rules = array(
            'apiToken'     => 'required|string',
            'state_id'     => 'required|numeric',
            'district_id'  => 'required|numeric',
            'territory_id' => 'required|numeric',
            'market'       => 'required|string',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $api_token   = $data['apiToken'];
            $user = $this->findUser($api_token);
            if ($user && count($user) == 1) {
                $user_id = $user[0]->id;
                $user_type = $user[0]->user_type;

                $app_version = isset($data['app_version']) ? $data['app_version'] : '';
                $app_version_data = array(
                    'user_id' => $user_id,
                    'user_type' => $user_type,
                    'app_version' => $app_version
                );
                $insert_version = AppVersion::firstOrCreate($app_version_data);

                try {
                    $states        = $data['state_id'];
                    $district_id   = $data['district_id'];
                    $territory_id  = $data['territory_id'];
                    $market     = $data['market'];
                    $marketdata = array(
                        'district_id'  => $district_id,
                        'territory_id' => $territory_id,
                        'market'       => $market,
                        'added_by'     => $user_id,
                        'status'       => '1',
                        'created_at'   => date('Y-m-d H:i:s'),
                        'updated_at'   => date('Y-m-d H:i:s'),
                    );
                    $insert_market = markets::firstOrCreate($marketdata);
                    $market_id = $insert_market->id;
                    if($market_id) {
                        $userData = User::where('id', $user_id)->where('status', '1')->first();
                        if($userData->market!=NULL) {
                            $crrMarket    = str_replace(']', ',', $userData->market);
                            $updateMarket = $crrMarket.'"'.$market_id.'"]';
                        } else {
                            $updateMarket = '["'.$market_id.'"]';
                        }

                        $updated_values = array(
                            'market' => $updateMarket,
                        );
                        DB::table('users')->where('id', $user_id)->update($updated_values);
                        $market_list = markets::where('market_id', $market_id)->where('territory_id', $territory_id)->get()->toArray();
                        return $this->respond([
                            'status' => 'success',
                            'status_code' => $this->getStatusCode(),
                            'message' => 'Market List Found!',
                            'data' => $market_list,
                        ]);
                    } else {
                        return $this->respondWithError("Error in adding market!");
                    }
                } catch (Exception $e) {
                    return $this->respondInternalError("An error occurred while performing an action!");
                }
            } else {
                return $this->respondWithConflict("Invalid Attempt!");
            }
        }
    }

