                    $brands              = $data['brands'];
                    $connected_retailers = $data['connected_retailers'];
                    $ratings             = $data['ratings'];
                    $pesticide_turnover  = $data['pesticide_turnover'];
                    $counter_percentage_pesticides  = (!empty($data['counter_percentage_pesticides'])) ? $data['counter_percentage_pesticides'] : NULL;
                    
                    $distributerdata = array(
                        'state_id'            => $state_id,
                        'district_id'         => $district_id,
                        'territory_id'        => $territory_id,
                        'market'              => $market,
                        'distributer_name'    => $distributer_name,
