                } catch (Exception $e) {
                    return $this->respondInternalError("An error occurred while performing an action!");
                }
            } else {
                return $this->respondWithConflict("Invalid Attempt!");
            }
        }
    }


    /* Graph API For By ECN and District */
    public function graphapiDistributer(Request $request) {
        $data = $request->all();
        $rules = array(
            'ecnnumber'   => 'required',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $ecnnumber   = $data['ecnnumber'];
            try {
                $user = User::where('ECN', $ecnnumber)->first();
                $user_districts = $user['districts'];
                $user_territory = $user['territory'];
                $user_market    = $user['market'];
                $territoryArr   = array();
                $marketArr      = array();
                if($user_districts!=NULL) {
                    $districts = str_replace('"', "", str_replace('[', "",str_replace(']', "",$user_districts)));
                    $districtArr = explode(',',$districts);
                    
                    if($user_territory!=NULL) {
                        $territory = str_replace('"', "", str_replace('[', "",str_replace(']', "",$user_territory)));
                        $territoryArr = explode(',',$territory);
                    }

                    if($user_market!=NULL) {
                        $market = str_replace('"', "", str_replace('[', "",str_replace(']', "",$user_market)));
                        $marketArr = explode(',',$market);
                    }

                    if(count($districtArr)>0) {
                        $district_list = District::whereIn('district_id', $districtArr)->get()->toArray();
                        if (count($district_list) > 0) {
                            $data = array();
                            $a=0;
                            foreach ($district_list as $key => $district) {
                                $district_id = $district['district_id'];
                                $admin_distributor = DB::table('distributers')->where('addedbyecn', 1)->where('district_id', $district_id)->whereIn('territory_id', $territoryArr)->whereIn('market', $marketArr)->count();

                                $rating_distributor = DB::table('distributers')->where('addedbyecn', 1)->where('district_id', $district_id)->whereIn('territory_id', $territoryArr)->whereIn('market', $marketArr)->where('ratings', '<>', '')->count();
                                
                                $nonrating_distributor = DB::table('distributers')->where('addedbyecn', 1)->where('district_id', $district_id)->whereIn('territory_id', $territoryArr)->whereIn('market', $marketArr)->where('ratings', '')->count();
                                
                                $distributor_by_ecn = DB::table('distributers')->where('addedbyecn', $ecnnumber)->where('district_id', $district_id)->count();
                                
                                $data[$a]['state_id'] = $district['state_id'];
                                $data[$a]['district_id'] = $district['district_id'];
                                $data[$a]['district'] = $district['district'];
                                $data[$a]['admin_distributor'] = $admin_distributor;
                                $data[$a]['rating_distributor'] = $rating_distributor;
                                $data[$a]['nonrating_distributor'] = $nonrating_distributor;
                                $data[$a]['distributor_by_ecn'] = $distributor_by_ecn;
                                $a++;
                            }
                        } else {
                            $data = "No District Found!";
                        }
                    } else {
                        $data = "No District Found!";
                    }
                } else {
                    $data = "No District Found!";
                }
                
                return $this->respond([
                    'status' => 'success',
                    'status_code' => $this->getStatusCode(),
                    'message' => 'Distributor Graph Detail Found!',
                    'data'  => $data,
                ]);
            } catch (Exception $e) {
                return $this->respondInternalError("An error occurred while performing an action!");
            }
        }
    }

