    /* List Formulation By Class_id */
    public function getlistformulation(Request $request) {
        $data = $request->all();
        $rules = array(
            'class_id'    => 'required|numeric',
            'district_id' => 'required|numeric',
            'ecn'         => 'required',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $class_id    = $data['class_id'];
            $ecnnumber   = $data['ecn'];
            $district_id = $data['district_id'];
            try {
                $dwData = DB::table('dccompanywise')->select('formulation_id')->where('ecnnumber', $ecnnumber)->where('district_id', $district_id)->where('status', 3)->groupBy('formulation_id')->get();
                $dwresult = array();
                if (isset($dwData) && !empty($dwData)) {
                    $dwresultss = json_decode(json_encode($dwData),true);
                    foreach ($dwresultss as $key => $value) {
                        if (is_array($value)) {
                            $dwresult = array_merge($dwresult, array_flatten($value));
                        } else {
                            $dwresult[$key] = $value;
                        }
                    }
                }
                $dwDataMerge = implode("','", $dwresult);
                // $formulation_list = Formulation::where('class_id', $class_id)->get()->toArray();
                $query = "SELECT * FROM formulation WHERE class_id='".$class_id."' AND f_id NOT IN ('".$dwDataMerge."') GROUP BY f_id";
                $formulation_list = DB::select(DB::raw($query));
                if (count($formulation_list) > 0) {
                    return $this->respond([
                        'status' => 'success',
                        'status_code' => $this->getStatusCode(),
                        'message' => 'Formulation List Found!',
                        'data' => $formulation_list,
                    ]);
                } else {
                    return $this->respondWithConflict("No Data Found!");
                }
            } catch (Exception $e) {
                return $this->respondInternalError("An error occurred while performing an action!");
            }
        }
    }

