    /* List Districtwise Data Collection */
    public function getlistdcdiscrict(Request $request) {
        $addQry = "";
        $data   = $request->all();
        $rules  = array(
            'apiToken' => 'required|string',
            'status'   => 'numeric',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $api_token = $data['apiToken'];
            $user = $this->findUser($api_token);

            if ($user && count($user) == 1) {
                $user_id = $user[0]->id;
                $user_type = $user[0]->user_type;
                $ecnnumber = $user[0]->ECN;

                $app_version = isset($data['app_version']) ? $data['app_version'] : '';
                $app_version_data = array(
                    'user_id' => $user_id,
                    'user_type' => $user_type,
                    'app_version' => $app_version
                );
                $insert_version = AppVersion::firstOrCreate($app_version_data);

                if(!empty($data['status'])) {
                    $status = $data['status'];
                    if($status >0 && $status<4) {
                        $addQry = "AND dw.status='".$status."'";
                    } else {
                        return $this->respondValidationError('Fields Validation Failed.','status value should be between 1 to 3');
                    }
                }

                try {
                    // $dcdata_list = Dcdistrictwise::where('ecnnumber', $ecnnumber)->get()->toArray();
                    $query = "SELECT 
                                dw.id,
                                dw.ecnnumber,
                                dw.ecnname,
                                s.state,
                                d.district,
                                c.name as classname,
                                f.name as formulationname,
                                f.brand,
                                f.nrv,
                                dw.volume,
                                dw.value,
                                dw.status,
                                dw.remarks,
                                dw.created_at,
                                dw.updated_at
                            FROM        dcdistrictwise         dw
                            LEFT JOIN   states          s   ON dw.state_id=s.state_id
                            LEFT JOIN   districts       d   ON dw.district_id=d.district_id
                            LEFT JOIN   class           c   ON dw.class_id=c.class_id
                            LEFT JOIN   formulation     f   ON dw.formulation_id=f.f_id
                            WHERE  ecnnumber='".$ecnnumber."' $addQry order by dw.id DESC";
                    
                    $dcdata_list = DB::select(DB::raw($query));

                    if (count($dcdata_list) > 0) {
                        return $this->respond([
                            'status' => 'success',
                            'status_code' => $this->getStatusCode(),
                            'message' => 'Districtwise Data Collection List Found!',
                            'data' => $dcdata_list,
                        ]);
                    } else {
                        return $this->respondWithError("Data Item Not Found!");
                    }
                } catch (Exception $e) {
                    return $this->respondInternalError("An error occurred while performing an action!");
                }
            } else {
                return $this->respondWithConflict("Invalid Attempt!");
            }
        }
    }

