    /* Add Districtwise Data */
    public function adddiscrictdata(Request $request) {
        $data = $request->all();
        $rules = array(
            'apiToken'          => 'required|string',
            'state_id'          => 'required|numeric',
            'district_id'       => 'required|numeric',
            'class_id'          => 'required|numeric',
            'formulation_id'    => 'required|numeric',
            'volume'            => 'required|numeric',
            'remarks'           => 'required'
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $api_token   = $data['apiToken'];
            $user = $this->findUser($api_token);
            if ($user && count($user) == 1) {
                $user_id = $user[0]->id;
                $user_type = $user[0]->user_type;

                $app_version = isset($data['app_version']) ? $data['app_version'] : '';
                $app_version_data = array(
                    'user_id' => $user_id,
                    'user_type' => $user_type,
                    'app_version' => $app_version
                );
                $insert_version = AppVersion::firstOrCreate($app_version_data);

                try {
                    $ecnnumber          = $user[0]->ECN;
                    $ecnname            = $user[0]->name;
                    $state_id           = $data['state_id'];
                    $district_id        = $data['district_id'];
                    $class_id           = $data['class_id'];
                    $formulation_id     = $data['formulation_id'];
                    $volume             = $data['volume'];
                    $remarks            = $data['remarks'];

                    $fdata  = $this->getformulationDetail($formulation_id,$class_id);
                    $nrv    = ($fdata[0]['nrv']) ? $fdata[0]['nrv'] : 0;
                    $value  = $volume*$nrv;
                    $status = ($value>0) ? 2 : 1;

                    $data_arr = array(
                        'ecnnumber'         => $ecnnumber,
                        'ecnname'           => $ecnname,
                        'state_id'          => $state_id,
                        'district_id'       => $district_id,
                        'class_id'          => $class_id,
                        'formulation_id'    => $formulation_id,
                        'volume'            => $volume,
                        'value'             => $value,
                        'status'            => $status,
                        'remarks'           => $remarks,
                        'created_at'        => date('Y-m-d H:i:s'),
                        'updated_at'        => date('Y-m-d H:i:s')
                    );
                    $insert_data     = Dcdistrictwise::firstOrCreate($data_arr);
                    $data_id         = $insert_data->id;
                    if($insert_data) {
