    /* Companywise Data Detail */
    public function companydatadetail(Request $request) {
        $data = $request->all();
        $rules = array(
            'id'    => 'required|numeric',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $id   = $data['id'];
            try {
                $id    = $data['id'];
                $query = "SELECT
                            dc.ecnnumber,
                            dc.ecnname,
                            s.state,
                            d.district,
                            c.name as classname,
                            f.name as formulationname,
                            dc.volume,
                            dc.value,
                            dc.adama,
                            dc.atul,
                            dc.bayer,
                            dc.basf,
                            dc.bharat_certis,
                            dc.bio_stadt,
                            dc.cheminova,
                            dc.coromandal_inter_ltd,
                            dc.coromandel_agri_co,
                            dc.crystal,
                            dc.corteva,
                            dc.devidayal,
                            dc.dhanuka_agritech,
                            dc.excel_crop_care,
                            dc.fil,
                            dc.fmc,
                            dc.gharda_chemicals,
                            dc.godrej_agrovet_ltd,
                            dc.gsp,
                            dc.hindustan_insecticides_ltd,
                            dc.hindustan_pulverising,
                            dc.hpm,
                            dc.heranba,
                            dc.indofil,
                            dc.indo_gulf,
                            dc.insecticides_india_ltd,
                            dc.ichiban,
                            dc.ipl,
                            dc.ju_agri_science,
                            dc.jubilant,
                            dc.krishi_rasayan,
                            dc.meghmani,
                            dc.nagarjuna_agri_chem,
                            dc.nichino,
                            dc.multiplex,
                            dc.mahindra,
                            dc.pi_industries,
                            dc.parijat,
                            dc.punjab_chemicals,
                            dc.rallis,
                            dc.safex,
                            dc.shivalik_crop,
                            dc.sudarshan_chemical,
                            dc.sulphur_mills,
                            dc.sumitomo,
                            dc.swal_corporation,
                            dc.syngenta,
                            dc.upl_ltd,
                            dc.willowood_crop_sciences,
                            dc.zuari_agro_chemicals,
                            dc.others,
                            dc.grand_total,
                            dc.status,
                            dc.created_at,
                            dc.updated_at
                        FROM        dccompanywise   dc
                        LEFT JOIN   states          s   ON dc.state_id=s.state_id
                        LEFT JOIN   districts       d   ON dc.district_id=d.district_id
                        LEFT JOIN   class           c   ON dc.class_id=c.class_id
                        LEFT JOIN   formulation     f   ON dc.formulation_id=f.f_id
                        WHERE dc.id='".$id."' order by dc.id DESC";
                
                $dcdata_list = DB::select(DB::raw($query));

                if (count($dcdata_list) > 0) {
                    return $this->respond([
                        'status' => 'success',
                        'status_code' => $this->getStatusCode(),
                        'message' => 'Companywise Data Collection Detail Found!',
                        'data' => $dcdata_list,
                    ]);
                } else {
                    return $this->respondWithError("Data Item Not Found!");
                }
            } catch (Exception $e) {
                return $this->respondInternalError("An error occurred while performing an action!");
            }
        }
    }


    public function graphapiChemical(Request $request) {
        $data = $request->all();
        $rules = array(
            'district_id' => 'required|numeric',
            'ecnnumber'   => 'required',
        );
        $validator = Validator::make($data, $rules);
        if ($validator->fails()) {
            return $this->respondValidationError('Fields Validation Failed.', $validator->errors());
        } else {
            $district_id = $data['district_id'];
            $ecnnumber   = $data['ecnnumber'];
            try {
                $query = "SELECT count(*) FROM formulation GROUP BY f_id";
                $formulation_list = DB::select(DB::raw($query));
                $totalFormulation = count($formulation_list);

                $dcData = DB::table('dccompanywise')->select('formulation_id')->where('ecnnumber', $ecnnumber)->where('district_id', $district_id)->where('status', 3)->groupBy('formulation_id')->get();
                $totaldcData = count($dcData);

                return $this->respond([
                    'status' => 'success',
                    'status_code' => $this->getStatusCode(),
                    'message' => 'Chemical Graph Detail Found!',
                    'total_formulation' => $totalFormulation,
                    'total_companyData' => $totaldcData,
                ]);
            } catch (Exception $e) {
                return $this->respondInternalError("An error occurred while performing an action!");
            }
        }
    }

